svg.script:
(function () {
  var DUR = 8000;

var readout = document.getElementById('moon-lit-readout');
var pLine = document.getElementById('pat-line');
var pTrace = document.getElementById('pat-trace');
var pArea = document.getElementById('pat-area');
var pOval = document.getElementById('pat-oval');
var pNum = document.getElementById('pat-num');
var pDot = document.getElementById('pat-dot');
var pHalo = document.getElementById('pat-halo');
var pPts = [[96,514],[186,504],[276,498],[366,534],[456,558],[546,616],[636,616],[720,652],[794,650]];
function renderAt(p) {
  var s = Math.sin(2 * Math.PI * p);
  if (readout) {
    var k = 0.48 + 0.29 * s;
    readout.textContent = Math.round(k * 100) + '% LIT  ·  GALAXY SCORE™  ·  ALTRANK™';
  }
  var pts = pPts.map(function (pt, idx) {
    var w = Math.max(0, (idx - 2) / 6);
    var dy = -34 * s * w;
    return [pt[0], Number((pt[1] + dy).toFixed(1))];
  });
  var d = pts.map(function (pt, idx) { return (idx === 0 ? 'M ' : 'L ') + pt[0] + ' ' + pt[1]; }).join(' ');
  var a = d + ' L 794 824 L 96 824 Z';
  if (pLine) pLine.setAttribute('d', d);
  if (pTrace) pTrace.setAttribute('d', d);
  if (pArea) pArea.setAttribute('d', a);
  var endPt = pts[pts.length - 1];
  if (pDot) pDot.setAttribute('cy', endPt[1]);
  if (pHalo) {
    pHalo.setAttribute('cy', endPt[1]);
    pHalo.style.transformOrigin = endPt[0] + 'px ' + endPt[1] + 'px';
  }
  if (pOval) pOval.setAttribute('transform', 'translate(708 ' + (608 + (endPt[1] - 650)).toFixed(1) + ')');
  if (pNum) pNum.textContent = Math.round(48 + 9 * s) + '%';
}

  var manual = false;
  window.__seekSvgTime = function (tMs) {
    manual = true;
    renderAt((((tMs / DUR) % 1) + 1) % 1);
  };
  renderAt(0);
  if (typeof requestAnimationFrame === 'function') {
    var t0 = performance.now();
    function loop(now) {
      if (manual) return;
      renderAt(((now - t0) % DUR) / DUR);
      requestAnimationFrame(loop);
    }
    requestAnimationFrame(loop);
  }
})();
